import {CHURCH_LESSONS,KINGDOM_DATA} from './learning-data.mjs?v=20261108-aligned2';
const tracks={church:{title:'教會歷史',lessons:CHURCH_LESSONS},kingdoms:{title:'王國與先知',lessons:KINGDOM_DATA.lessons}};
const link=(url,text)=>`<a class="text-button" href="${url}">${text}</a>`;
function timeline(lessons,track,e){return `<ol class="history-timeline">${lessons.flatMap(l=>l.events.map(event=>({...event,lesson:l.id}))).sort((a,b)=>a.year-b.year).map(event=>`<li><a href="#/learn/${track}/${event.lesson}"><span>${e(event.date)}</span><strong>${e(event.text)}</strong></a></li>`).join('')}</ol>`;}
function lanes(lessons,e){return `<p class="note">概覽按歷史階段排列，唔按年數比例繪製。先知服事可能跨越多位君王，年代亦可能重疊；列出同期唔代表每位先知都向每位王傳話。統一王國放喺第一欄，未有南北之分。</p><div class="kingdom-lanes"><div class="lane-head"><span>時期</span><span>北國／統一王國</span><span>南國猶大</span><span>先知與信息</span></div>${lessons.map(l=>`<a class="lane-row" href="#/learn/kingdoms/${l.id}"><strong>${e(l.period)}</strong><span data-label="北國／統一王國">${e(l.north)}</span><span data-label="南國猶大">${e(l.south)}</span><span data-label="先知與信息">${e(l.prophets)}</span></a>`).join('')}</div>`;}
export function learningView(track,p,e){
 const t=tracks[track];
 if(!t)return `<div class="page-head"><div class="eyebrow">先認識背景，再連起故事</div><h1>歷史學習中心</h1><p>兩條學習線：讀短文、睇時間線，再用每課十題重溫。唔使一開始就死背年份。</p></div><div class="learning-tracks">${Object.entries(tracks).map(([id,t])=>`<article class="learning-track"><span class="eyebrow">10課 · 100題</span><h2>${t.title}</h2><p>${id==='church'?'由初期教會到中國同香港，了解人物、事件同背後原因。':'由掃羅到被擄歸回，對照南北國君王、先知同經文。'}</p><a class="button primary" href="#/learning/${id}">開始學習 →</a></article>`).join('')}</div>`;
 const done=t.lessons.filter(l=>p.learningReads?.[track+':'+l.id]?.done).length;
 const answers=track==='church'?p.courseAnswers:p.kingdomAnswers;
 const position=p.learningPositions?.[track]?.lesson;
 return `<a class="text-button" href="#/learning">← 歷史學習中心</a><div class="page-head"><div class="eyebrow">短文 · 時間線 · 操練</div><h1>${t.title}</h1><p>已讀 ${done}／10課 · 已操練 ${Object.keys(answers||{}).length}／100題。已讀標記由你自己設定，唔會增加 XP。</p></div>${position&&t.lessons.some(l=>l.id===position)?`<p>${link('#/learn/'+track+'/'+position,'繼續上次閱讀 →')}</p>`:''}<details class="learning-overview"><summary>打開總時間線${track==='kingdoms'?'及君王／先知對照':''}</summary>${timeline(t.lessons.filter(l=>l.id!=='reading'),track,e)}${track==='kingdoms'?lanes(t.lessons,e):'<p class="note">中國同香港課堂按專題安排；呢條總時間線按實際事件年代排序。閱讀方法課唔屬歷史年代。</p>'}${track==='kingdoms'?`<details><summary>南北國君王完整次序</summary><div class="ruler-lists"><section><h3>北國以色列</h3><ol>${KINGDOM_DATA.rulers.north.map(n=>`<li>${e(n)}</li>`).join('')}</ol></section><section><h3>南國猶大</h3><ol>${KINGDOM_DATA.rulers.south.map(n=>`<li>${e(n)}</li>`).join('')}</ol></section></div><p>同名君王分屬不同國家；王位可能有共同執政或爭位。</p></details>`:''}</details><div class="course-grid">${t.lessons.map((l,i)=>`<article class="course-unit"><div class="course-unit-top"><span class="course-number">${String(i+1).padStart(2,'0')}</span><span class="pill sage">${p.learningReads?.[track+':'+l.id]?.done?'已讀':'未標記已讀'}</span></div><p>${e(l.period)}</p><h2>${e(l.title)}</h2><p>${e(l.summary)}</p><div class="actions"><a class="button secondary small" href="#/learn/${track}/${l.id}">讀呢課 →</a><button class="text-button" data-action="start" data-mode="${track}" data-unit="${l.id}">操練10題</button></div></article>`).join('')}</div>`;
}
export function lessonView(track,id,p,e){
 const t=tracks[track],index=t?.lessons.findIndex(l=>l.id===id),l=t?.lessons[index];
 if(!l)return '<h1>搵唔到呢課</h1><a href="#/learning">返去歷史學習中心</a>';
 return `<a class="text-button" href="#/learning/${track}">← ${t.title}課程</a><article class="learning-article"><div class="eyebrow">第${index+1}課 · ${e(l.period)}</div><h1>${e(l.title)}</h1><aside class="lesson-summary"><h2>先記住呢點</h2><p>${e(l.summary)}</p></aside>${l.paragraphs.map(text=>`<p>${e(text)}</p>`).join('')}<h2>${track==='church'&&id==='reading'?'閱讀步驟':'今課時間線'}</h2>${timeline([l],track,e)}${track==='kingdoms'?lanes([l],e):''}<div class="lesson-actions"><button class="button secondary" data-action="mark-read" data-id="${track}:${id}">${p.learningReads?.[track+':'+id]?.done?'已讀呢課 · 取消標記':'我睇完呢課'}</button><button class="button primary" data-action="start" data-mode="${track}" data-unit="${id}">操練今課10題 →</button></div><nav class="lesson-pager" aria-label="閱讀課堂">${index>0?link('#/learn/'+track+'/'+t.lessons[index-1].id,'← 上一課'):'<span></span>'}${index<9?link('#/learn/'+track+'/'+t.lessons[index+1].id,'下一課 →'):link('#/learning/'+track,'返去課程 →')}</nav></article>`;
}
